def add_comment(session, post_id, author_id, body):
    post = session.get(Post, post_id)
    if post is None or post.locked:
        raise ValueError("cannot comment on this post")
    body = body.strip()
    if not body:
        raise ValueError("empty comment")
    comment = Comment(post_id=post_id, author_id=author_id, body=body)
    session.add(comment)
    post.comment_count = (post.comment_count or 0) + 1
    session.commit()
    return {"id": comment.id, "post": post_id, "count": post.comment_count}

