def fill_template(template, values, missing="?"):
    out, i = [], 0
    while i < len(template):
        if template.startswith("{{", i):
            out.append("{")
            i += 2
        elif template.startswith("}}", i):
            out.append("}")
            i += 2
        elif template[i] == "{":
            end = template.find("}", i)
            if end == -1:
                raise ValueError("unclosed placeholder")
            name = template[i + 1:end].strip()
            out.append(str(values.get(name, missing)))
            i = end + 1
        else:
            out.append(template[i])
            i += 1
    return "".join(out)

