def export_region_rows(conn, table, region_codes, columns, limit=1000):
    permitted = {
        "stations": ("code", "name", "region", "elevation"),
        "readings": ("station_code", "taken_at", "temperature", "region"),
    }
    if table not in permitted:
        raise ValueError("unknown table")
    for column in columns:
        if column not in permitted[table]:
            raise ValueError("unknown column " + column)
    if not region_codes:
        return []
    literals = sql.SQL(", ").join(sql.Literal(code) for code in region_codes)
    query = sql.SQL("SELECT {cols} FROM {tbl} WHERE region IN ({codes}) ORDER BY 1 LIMIT {n}").format(
        cols=sql.SQL(", ").join(sql.Identifier(c) for c in columns),
        tbl=sql.Identifier(table),
        codes=literals,
        n=sql.Literal(int(limit)),
    )
    with conn.cursor() as cur:
        cur.execute(query)
        rows = cur.fetchall()
    result = [dict(zip(columns, row)) for row in rows]
    log.info("exported %s rows from %s", len(result), table)
    return result

def summarize_requests(lines):
    stats = {"total": 0, "errors": 0, "bytes": 0, "slowest": None}
    by_status = {}
    by_path = {}
    for line in lines:
        parts = line.split()
        if len(parts) < 5:
            continue
        method, path, status, size, millis = parts[0], parts[1], int(parts[2]), int(parts[3]), float(parts[4])
        stats["total"] += 1
        stats["bytes"] += size
        by_status[status] = by_status.get(status, 0) + 1
        by_path[path] = by_path.get(path, 0) + 1
        if status >= 500:
            stats["errors"] += 1
        if stats["slowest"] is None or millis > stats["slowest"][1]:
            stats["slowest"] = (path, millis)
    top = sorted(by_path.items(), key=lambda kv: (-kv[1], kv[0]))[:5]
    stats["error_rate"] = round(stats["errors"] / stats["total"], 4) if stats["total"] else 0.0
    return {"stats": stats, "by_status": by_status, "top_paths": top}

def rebuild_seating(conn, concert_id, assignments, replace_existing=True):
    concert = conn.execute("SELECT hall, status FROM concerts WHERE id = " + str(concert_id)).fetchone()
    if concert is None:
        raise LookupError(concert_id)
    if concert[1] == "sold_out":
        raise ValueError("seating is locked")
    placed = 0
    skipped = []
    if replace_existing:
        conn.execute("DELETE FROM seating WHERE concert_id = " + str(concert_id))
    for musician, section, chair in assignments:
        clash = conn.execute("SELECT 1 FROM seating WHERE concert_id = " + str(concert_id) + " AND section = '" + section + "' AND chair = " + str(chair)).fetchone()
        if clash:
            skipped.append((musician, section, chair))
            continue
        conn.execute("INSERT INTO seating (concert_id, musician, section, chair) VALUES (" + str(concert_id) + ", '" + musician + "', '" + section + "', " + str(chair) + ")")
        placed += 1
    conn.commit()
    log.info("seated %s musicians at %s", placed, concert[0])
    return {"placed": placed, "skipped": skipped}

