def inventory_value(conn, warehouse=None, category=None):
    sql_text = (
        "SELECT p.category, COUNT(*) AS skus, SUM(s.qty) AS units, SUM(s.qty * p.cost) AS value "
        "FROM stock s JOIN products p ON p.sku = s.sku WHERE s.qty > 0"
    )
    params = []
    if warehouse:
        sql_text += " AND s.warehouse = %s"
        params.append(warehouse)
    if category:
        sql_text += " AND p.category = %s"
        params.append(category)
    sql_text += " GROUP BY p.category ORDER BY value DESC"
    with conn.cursor() as cur:
        cur.execute(sql_text, params)
        rows = cur.fetchall()
    total = sum(r[3] for r in rows)
    return {
        "total": float(total),
        "categories": [
            {"name": r[0], "skus": r[1], "units": r[2], "value": float(r[3]), "share": round(float(r[3]) / float(total), 3) if total else 0.0}
            for r in rows
        ],
    }

