def team_dashboard(team, since):
    tasks = Task.objects.filter(project__team=team)
    open_tasks = tasks.filter(done=False)
    finished = tasks.filter(done=True, finished_at__gte=since)
    by_person = (
        finished.values("assignee__username")
        .annotate(n=Count("id"), minutes=Sum("estimate_minutes"))
        .order_by("-n")
    )
    overdue = open_tasks.filter(due__lt=timezone.now()).select_related("assignee", "project")
    busiest = (
        open_tasks.values("assignee__username")
        .annotate(n=Count("id"))
        .order_by("-n")
        .first()
    )
    return {
        "open": open_tasks.count(),
        "finished": finished.count(),
        "by_person": [
            {"user": row["assignee__username"], "tasks": row["n"], "minutes": row["minutes"] or 0}
            for row in by_person
        ],
        "overdue": [
            {"id": t.id, "title": t.title, "assignee": t.assignee.username, "project": t.project.name}
            for t in overdue[:20]
        ],
        "busiest": busiest["assignee__username"] if busiest else None,
    }

