def split_into_weeks(days, start_weekday=0):
    weeks, week = [], []
    for day in days:
        week.append(day)
        if (day.weekday() - start_weekday) % 7 == 6:
            weeks.append(week)
            week = []
    if week:
        weeks.append(week)
    return weeks

def working_days(start, end):
    if end < start:
        raise ValueError("end before start")
    days = 0
    current = start
    while current <= end:
        if current.weekday() < 5:
            days += 1
        current += timedelta(days=1)
    return days

