@app.route("/api/orders/<int:order_id>", methods=["PATCH"])
def update_order(order_id):
    data = request.get_json() or {}
    action = data.get("action")
    actor = session.get("user_id")
    if actor is None:
        return jsonify(error="sign in first"), 401
    with get_conn() as conn, conn.cursor() as cur:
        cur.execute("SELECT status, customer_id, total FROM orders WHERE id = %s FOR UPDATE", (order_id,))
        row = cur.fetchone()
        if row is None:
            return jsonify(error="not found"), 404
        status, customer_id, total = row
        if action == "pay":
            if status != "new":
                return jsonify(error="order is not awaiting payment"), 409
            cur.execute("UPDATE orders SET status = 'paid', paid_at = now() WHERE id = %s", (order_id,))
            cur.execute("INSERT INTO payments (order_id, amount, method) VALUES (%s, %s, %s)", (order_id, total, data.get("method", "card")))
        elif action == "ship":
            if status != "paid":
                return jsonify(error="order is not paid"), 409
            carrier = data.get("carrier")
            tracking = data.get("tracking")
            if not carrier or not tracking:
                return jsonify(error="carrier and tracking are required"), 400
            cur.execute("UPDATE orders SET status = 'shipped', shipped_at = now() WHERE id = %s", (order_id,))
            cur.execute("INSERT INTO shipments (order_id, carrier, tracking) VALUES (%s, %s, %s)", (order_id, carrier, tracking))
        elif action == "cancel":
            if status in ("shipped", "cancelled"):
                return jsonify(error="order can no longer be cancelled"), 409
            cur.execute("UPDATE orders SET status = 'cancelled' WHERE id = %s", (order_id,))
            cur.execute("UPDATE stock s SET qty = s.qty + l.qty FROM order_lines l WHERE l.order_id = %s AND s.sku = l.sku", (order_id,))
        else:
            return jsonify(error="unknown action"), 400
        cur.execute("INSERT INTO order_events (order_id, actor_id, action) VALUES (%s, %s, %s)", (order_id, actor, action))
        cur.execute("SELECT status FROM orders WHERE id = %s", (order_id,))
        new_status = cur.fetchone()[0]
    logger.info("order %s: %s -> %s by %s", order_id, status, new_status, actor)
    return jsonify(id=order_id, status=new_status)

