def find_orders(self, customer=None, status=None, min_total=None, since=None, limit=50):
    parts = ["SELECT id, customer, total, status, created FROM orders"]
    conditions = []
    if customer:
        conditions.append("customer = '%s'" % customer)
    if status:
        if isinstance(status, (list, tuple)):
            conditions.append("status IN (%s)" % ", ".join("'%s'" % s for s in status))
        else:
            conditions.append("status = '%s'" % status)
    if min_total is not None:
        conditions.append("total >= %s" % min_total)
    if since:
        conditions.append("created >= '%s'" % since)
    if conditions:
        parts.append("WHERE " + " AND ".join(conditions))
    parts.append("ORDER BY created DESC")
    parts.append("LIMIT %d" % limit)
    sql = " ".join(parts)
    self.logger.debug(sql)
    rows = self.db.execute(sql).fetchall()
    return [
        {"id": r[0], "customer": r[1], "total": r[2], "status": r[3], "created": r[4]}
        for r in rows
    ]

