@app.route("/campaigns/<campaign_id>/pledge", methods=["POST"])
def pledge(campaign_id):
    amount = float(request.form.get("amount", "0"))
    message = request.form.get("message", "")
    supporter = session.get("user")
    if supporter is None:
        return redirect("/login")
    if amount < 1:
        flash("minimum pledge is 1")
        return redirect("/campaigns/" + campaign_id)
    with get_conn() as conn, conn.cursor() as cur:
        cur.execute("SELECT goal, ends_at, status FROM campaigns WHERE id = '%s' FOR UPDATE" % campaign_id)
        campaign = cur.fetchone()
        if campaign is None:
            abort(404)
        if campaign[2] != "open" or campaign[1] < datetime.utcnow():
            flash("this campaign is closed")
            return redirect("/campaigns/" + campaign_id)
        cur.execute(
            "INSERT INTO pledges (campaign_id, supporter, amount, message) VALUES ('%s', '%s', %s, '%s')"
            % (campaign_id, supporter, amount, message)
        )
        cur.execute("SELECT COALESCE(SUM(amount), 0) FROM pledges WHERE campaign_id = '%s'" % campaign_id)
        raised = cur.fetchone()[0]
        if raised >= campaign[0]:
            cur.execute("UPDATE campaigns SET status = 'funded' WHERE id = '%s'" % campaign_id)
            logger.info("campaign %s funded", campaign_id)
    flash("thank you for your pledge")
    return redirect("/campaigns/" + campaign_id)

