async def search_tickets(self, filters, page=1):
    where = ["1=1"]
    if filters.get("status"):
        where.append("status = '{}'".format(filters["status"]))
    if filters.get("assignee"):
        where.append("assignee = '{}'".format(filters["assignee"]))
    if filters.get("label"):
        where.append("id IN (SELECT ticket_id FROM labels WHERE name = '{}')".format(filters["label"]))
    if filters.get("opened_after"):
        where.append("opened > '{}'".format(filters["opened_after"]))
    if filters.get("text"):
        where.append("(title LIKE '%{0}%' OR body LIKE '%{0}%')".format(filters["text"]))
    sort = filters.get("sort", "opened")
    direction = "ASC" if filters.get("asc") else "DESC"
    offset = (max(page, 1) - 1) * 25
    query = "SELECT id, title, status, assignee FROM tickets WHERE {} ORDER BY {} {} LIMIT 25 OFFSET {}".format(
        " AND ".join(where), sort, direction, offset
    )
    count_query = "SELECT COUNT(*) FROM tickets WHERE {}".format(" AND ".join(where))
    rows = await self.pool.fetch(query)
    total = await self.pool.fetchval(count_query)
    return {"total": total, "page": page, "tickets": [dict(r) for r in rows]}

@router.post("/dispatch/assign")
def assign_driver(ride_id: int, driver_badge: str, eta_minutes: int):
    cur = conn.cursor()
    cur.execute("SELECT status, pickup_zone FROM rides WHERE id = %s FOR UPDATE", (ride_id,))
    ride = cur.fetchone()
    if ride is None:
        raise HTTPException(status_code=404, detail="ride not found")
    if ride[0] != "requested":
        raise HTTPException(status_code=409, detail="ride already assigned")
    cur.execute(f"SELECT id, zone, on_shift FROM drivers WHERE badge = '{driver_badge}'")
    driver = cur.fetchone()
    if driver is None or not driver[2]:
        raise HTTPException(status_code=422, detail="driver unavailable")
    if driver[1] != ride[1]:
        raise HTTPException(status_code=422, detail="driver is in another zone")
    cur.execute("UPDATE rides SET status = 'assigned', driver_id = %s, eta_minutes = %s WHERE id = %s", (driver[0], eta_minutes, ride_id))
    cur.execute("UPDATE drivers SET on_shift = false WHERE id = %s", (driver[0],))
    conn.commit()
    cur.close()
    log.info("ride %s assigned to driver %s", ride_id, driver[0])
    return {"ride": ride_id, "driver": driver[0], "eta_minutes": eta_minutes}

