def pack_batches(items, limit, size_of=len):
    batches, current, used = [], [], 0
    for item in items:
        size = size_of(item)
        if current and used + size > limit:
            batches.append(current)
            current, used = [], 0
        current.append(item)
        used += size
    if current:
        batches.append(current)
    return batches

def strip_accents(text):
