def balance_teams(players, teams=2):
    ranked = sorted(players, key=lambda p: p["skill"], reverse=True)
    groups = [{"members": [], "skill": 0} for _ in range(teams)]
    for player in ranked:
        target = min(groups, key=lambda g: (g["skill"], len(g["members"])))
        target["members"].append(player["name"])
        target["skill"] += player["skill"]
    spread = max(g["skill"] for g in groups) - min(g["skill"] for g in groups)
    return {"teams": [g["members"] for g in groups], "skills": [g["skill"] for g in groups], "spread": spread}

