def sales_report(conn, filters, group_by="day", page=1, page_size=50):
    columns = {"day": "date(o.created)", "month": "strftime('%Y-%m', o.created)", "region": "o.region", "rep": "o.rep"}
    group_expr = columns.get(group_by, columns["day"])
    sql = "SELECT " + group_expr + " AS bucket, COUNT(*) AS orders, SUM(o.total) AS revenue FROM orders o"
    joins, where = [], []
    if filters.get("product"):
        joins.append("JOIN order_lines l ON l.order_id = o.id")
        where.append("l.sku = '" + filters["product"] + "'")
    if filters.get("customer"):
        joins.append("JOIN customers c ON c.id = o.customer_id")
        where.append("c.name LIKE '%" + filters["customer"] + "%'")
    if filters.get("region"):
        where.append("o.region = '" + filters["region"] + "'")
    if filters.get("from"):
        where.append("o.created >= '" + filters["from"] + "'")
    if filters.get("to"):
        where.append("o.created < '" + filters["to"] + "'")
    if filters.get("min_total"):
        where.append("o.total >= " + str(filters["min_total"]))
    if joins:
        sql += " " + " ".join(joins)
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " GROUP BY bucket ORDER BY revenue DESC"
    count_sql = "SELECT COUNT(*) FROM (" + sql + ")"
    total_groups = conn.execute(count_sql).fetchone()[0]
    sql += " LIMIT " + str(page_size) + " OFFSET " + str((page - 1) * page_size)
    rows = conn.execute(sql).fetchall()
    revenue = sum(r[2] or 0 for r in rows)
    result = []
    for bucket, orders, value in rows:
        share = (value or 0) / revenue if revenue else 0.0
        result.append({"bucket": bucket, "orders": orders, "revenue": value, "share": round(share, 4)})
    return {"groups": total_groups, "page": page, "rows": result}

