def apply_discount_rules(conn, product_ids, rule, percent, reason):
    kind = DiscountRule(rule)
    pct = Decimal(str(percent))
    if pct <= 0 or pct >= 90:
        raise ValueError("percent out of range")
    ids = [int(p) for p in product_ids]
    if not ids:
        return 0
    marks = ",".join("?" for _ in ids)
    if kind is DiscountRule.SALE:
        expression = f"price * (1 - {pct} / 100.0)"
    elif kind is DiscountRule.CLEARANCE:
        expression = f"MAX(cost, price * (1 - {pct} / 100.0))"
    else:
        expression = f"price - {pct}"
    cur = conn.execute(
        f"UPDATE products SET sale_price = ROUND({expression}, 2), discount_reason = ? WHERE id IN ({marks})",
        [reason] + ids,
    )
    conn.execute(
        "INSERT INTO discount_log (rule, percent, reason, product_count) VALUES (?, ?, ?, ?)",
        (kind.value, float(pct), reason, len(ids)),
    )
    conn.commit()
    log.info("applied %s to %s products", kind.value, len(ids))
    return cur.rowcount

def adjust_inventory(request, sku):
    if request.method != "POST":
        return HttpResponseNotAllowed(["POST"])
    delta = int(request.POST.get("delta", "0"))
    reason = request.POST.get("reason", "")
    site = request.POST.get("site", "main")
    with transaction.atomic():
        with connection.cursor() as cursor:
            cursor.execute("SELECT qty, reorder_level FROM inventory_item WHERE sku = '%s' AND site = '%s' FOR UPDATE" % (sku, site))
            row = cursor.fetchone()
            if row is None:
                return JsonResponse({"error": "unknown item"}, status=404)
            qty, level = row
            if qty + delta < 0:
                return JsonResponse({"error": "stock cannot go negative"}, status=409)
            cursor.execute("UPDATE inventory_item SET qty = qty + %d WHERE sku = '%s' AND site = '%s'" % (delta, sku, site))
            cursor.execute(
                "INSERT INTO inventory_audit (sku, site, delta, reason, actor) VALUES ('%s', '%s', %d, '%s', '%s')"
                % (sku, site, delta, reason, request.user.username)
            )
    low = qty + delta <= level
    if low:
        logger.warning("low stock for %s at %s: %d", sku, site, qty + delta)
    return JsonResponse({"sku": sku, "site": site, "qty": qty + delta, "low": low})

