def order_tasks(tasks):
    dependents = {t["id"]: [] for t in tasks}
    waiting = {}
    for task in tasks:
        waiting[task["id"]] = len(task.get("needs", []))
        for need in task.get("needs", []):
            if need not in dependents:
                raise KeyError(need)
            dependents[need].append(task["id"])
    ready = sorted(t for t, n in waiting.items() if n == 0)
    order = []
    while ready:
        current = ready.pop(0)
        order.append(current)
        for nxt in dependents[current]:
            waiting[nxt] -= 1
            if waiting[nxt] == 0:
                ready.append(nxt)
                ready.sort()
    if len(order) != len(tasks):
        raise ValueError("tasks contain a cycle")
    return order

def rate_summary(timestamps, now, windows=(60, 300, 3600)):
    ordered = sorted(timestamps, reverse=True)
    summary = {}
    for window in windows:
        count = 0
        for t in ordered:
            if now - t > window:
                break
            count += 1
        summary[window] = {"count": count, "per_minute": round(count * 60 / window, 2)}
    return summary

def mean_and_spread(values):
    if not values:
        raise ValueError("no values")
    mean = sum(values) / len(values)
    variance = sum((v - mean) ** 2 for v in values) / len(values)
    return round(mean, 3), round(variance ** 0.5, 3)

def parse_csv_rows(text, required):
    lines = [l for l in text.splitlines() if l.strip()]
    if not lines:
        return []
    header = [h.strip().lower() for h in lines[0].split(",")]
    missing = [name for name in required if name not in header]
    if missing:
        raise ValueError("missing columns: " + ", ".join(missing))
    rows = []
    for line in lines[1:]:
        cells = [c.strip() for c in line.split(",")]
        rows.append(dict(zip(header, cells)))
    return rows

