def route_distances(points, start=0):
    n = len(points)
    if n == 0:
        return []
    visited = [False] * n
    order = [start]
    visited[start] = True
    total = 0.0
    current = start
    for _ in range(n - 1):
        best, best_d = None, float("inf")
        for j in range(n):
            if visited[j]:
                continue
            d = ((points[current][0] - points[j][0]) ** 2 + (points[current][1] - points[j][1]) ** 2) ** 0.5
            if d < best_d:
                best, best_d = j, d
        visited[best] = True
        order.append(best)
        total += best_d
        current = best
    return {"order": order, "length": round(total, 3)}

