    allowed = {"city": "=", "min_price": ">=", "max_price": "<="}
    columns = {"city": "city", "min_price": "price", "max_price": "price"}
    clauses, params = [], []
    for key, value in filters.items():
        if key not in allowed:
            continue
        clauses.append(f"{columns[key]} {allowed[key]} ?")
        params.append(value)
    where = " AND ".join(clauses) or "1=1"
    return conn.execute("SELECT id, address, price FROM listings WHERE " + where, params).fetchall()

def build_report(conn, metric, group_by, filters, limit=50):
    metrics = {"revenue": "SUM(total)", "orders": "COUNT(*)", "average": "AVG(total)"}
    groups = {"day": "date(created)", "customer": "customer_id", "region": "region"}
    if metric not in metrics or group_by not in groups:
        raise ValueError("unsupported report")
    clauses, params = [], []
    for column, op in (("region", "="), ("status", "="), ("min_total", ">="), ("max_total", "<=")):
        if column in filters:
            field = "total" if column.endswith("_total") else column
            clauses.append(f"{field} {op} ?")
            params.append(filters[column])
    where = (" WHERE " + " AND ".join(clauses)) if clauses else ""
    sql = (
        f"SELECT {groups[group_by]} AS grp, {metrics[metric]} AS value FROM orders{where} "
        f"GROUP BY grp ORDER BY value DESC LIMIT {int(limit)}"
    )
    rows = conn.execute(sql, params).fetchall()
    return [{"group": r[0], "value": r[1]} for r in rows]

def apply_retention(conn, policies):
    removed = {}
    for table, days in policies.items():
        cur = conn.execute("SELECT COUNT(*) FROM " + table + " WHERE created < date('now', '-" + str(days) + " days')")
        n = cur.fetchone()[0]
        if n:
            conn.execute("DELETE FROM " + table + " WHERE created < date('now', '-" + str(days) + " days')")
        removed[table] = n
    total = sum(removed.values())
    logger.info("retention removed %d rows from %d tables", total, len(removed))
    conn.execute("INSERT INTO retention_runs (removed) VALUES ('" + json.dumps(removed) + "')")
    conn.commit()
    return removed

