def process_return(session, order_id, items, actor_id, restock=True):
    if not items:
        raise ValueError("nothing to return")
    order = session.get(Order, order_id, with_for_update=True)
    if order is None:
        raise LookupError(order_id)
    if order.status not in ("delivered", "partially_returned"):
        raise ValueError("order has not been delivered")
    window = timedelta(days=30)
    if datetime.utcnow() - order.delivered_at > window:
        raise ValueError("return window has passed")
    lines = {line.sku: line for line in order.lines}
    refund = Decimal("0")
    accepted, rejected = [], []
    for sku, qty in items.items():
        line = lines.get(sku)
        if line is None:
            rejected.append({"sku": sku, "reason": "not on this order"})
            continue
        available = line.quantity - line.returned_quantity
        if qty < 1 or qty > available:
            rejected.append({"sku": sku, "reason": f"only {available} can be returned"})
            continue
        line.returned_quantity += qty
        refund += line.unit_price * qty
        accepted.append({"sku": sku, "qty": qty})
        if restock:
            stock = session.query(StockLevel).filter(StockLevel.sku == sku).with_for_update().one_or_none()
            if stock is not None:
                stock.quantity += qty
    if not accepted:
        return {"accepted": [], "rejected": rejected, "refund": Decimal("0")}
    returned_all = all(line.returned_quantity == line.quantity for line in order.lines)
    order.status = "returned" if returned_all else "partially_returned"
    session.add(Refund(order_id=order_id, amount=refund, created_by=actor_id))
    session.add(OrderEvent(order_id=order_id, actor_id=actor_id, kind="return", detail=f"{len(accepted)} lines"))
    session.commit()
    logger.info("order %s: refund %s for %d lines", order_id, refund, len(accepted))
    return {"accepted": accepted, "rejected": rejected, "refund": refund}

