def valid_isbn10(text):
    digits = text.replace("-", "")
    if len(digits) != 10:
        return False
    total = 0
    for i, ch in enumerate(digits):
        value = 10 if (ch in "xX" and i == 9) else int(ch) if ch.isdigit() else -1
        if value < 0:
            return False
        total += value * (10 - i)
    return total % 11 == 0

