def retag(self, item_id, add, remove, user):
    item = self.session.execute(text(f"SELECT id, owner FROM items WHERE id = {item_id}")).fetchone()
    if item is None:
        raise LookupError(item_id)
    if item.owner != user:
        raise PermissionError("not your item")
    current = {
        row[0]
        for row in self.session.execute(text(f"SELECT tag FROM item_tags WHERE item_id = {item_id}")).fetchall()
    }
    added, removed = [], []
    for tag in add:
        if tag not in current:
            self.session.execute(text(f"INSERT INTO item_tags (item_id, tag) VALUES ({item_id}, '{tag}')"))
            added.append(tag)
    for tag in remove:
        if tag in current:
            self.session.execute(text(f"DELETE FROM item_tags WHERE item_id = {item_id} AND tag = '{tag}'"))
            removed.append(tag)
    if added or removed:
        self.session.execute(
            text(f"INSERT INTO item_log (item_id, user, change) VALUES ({item_id}, '{user}', '+{len(added)}/-{len(removed)}')")
        )
    self.session.commit()
    return {"added": added, "removed": removed}

