def render_markdown(text):
    html = []
    in_list = False
    in_code = False
    for raw in text.splitlines():
        line = raw.rstrip()
        if line.startswith("```"):
            html.append("</pre>" if in_code else "<pre>")
            in_code = not in_code
            continue
        if in_code:
            html.append(line.replace("&", "&amp;").replace("<", "&lt;"))
            continue
        if line.startswith("- "):
            if not in_list:
                html.append("<ul>")
                in_list = True
            html.append("<li>" + line[2:] + "</li>")
            continue
        if in_list:
            html.append("</ul>")
            in_list = False
        if line.startswith("### "):
            html.append("<h3>" + line[4:] + "</h3>")
        elif line.startswith("## "):
            html.append("<h2>" + line[3:] + "</h2>")
        elif line.startswith("# "):
            html.append("<h1>" + line[2:] + "</h1>")
        elif line == "":
            html.append("")
        else:
            html.append("<p>" + line + "</p>")
    if in_list:
        html.append("</ul>")
    if in_code:
        html.append("</pre>")
    out = chr(10).join(html)
    for marker, tag in (("**", "strong"), ("_", "em")):
        parts = out.split(marker)
        out = parts[0]
        for i, part in enumerate(parts[1:], start=1):
            out += ("<" + tag + ">" if i % 2 else "</" + tag + ">") + part
    return out

def validate_form(data, rules):
    errors = {}
    cleaned = {}
    for field, rule in rules.items():
        value = data.get(field)
        if value is None or value == "":
            if rule.get("required"):
                errors[field] = "required"
            elif "default" in rule:
                cleaned[field] = rule["default"]
            continue
        kind = rule.get("type", str)
        try:
            value = kind(value)
        except (TypeError, ValueError):
            errors[field] = "must be " + kind.__name__
            continue
        if "min" in rule and value < rule["min"]:
            errors[field] = f"must be at least {rule['min']}"
        elif "max" in rule and value > rule["max"]:
            errors[field] = f"must be at most {rule['max']}"
        elif "choices" in rule and value not in rule["choices"]:
            errors[field] = "not an allowed value"
        else:
            cleaned[field] = value
    return cleaned, errors

