    return lines

def rescale(values, low=0.0, high=100.0):
    if not values:
        return []
    smallest, largest = min(values), max(values)
    if smallest == largest:
        return [(low + high) / 2 for _ in values]
    span = largest - smallest
    return [low + (v - smallest) / span * (high - low) for v in values]

