def column_summary(conn, table, column):
    with conn.cursor() as cur:
        cur.execute(
            "SELECT 1 FROM information_schema.columns WHERE table_name = %s AND column_name = %s",
            (table, column),
        )
        if cur.fetchone() is None:
            raise ValueError("unknown column")
        cur.execute(
            sql.SQL("SELECT MIN({c}), MAX({c}), COUNT({c}) FROM {t}").format(c=sql.Identifier(column), t=sql.Identifier(table))
        )
        low, high, count = cur.fetchone()
    return {"table": table, "column": column, "min": low, "max": high, "count": count}

