def next_run(last_run, interval_minutes, active_hours=(8, 18)):
    candidate = last_run + timedelta(minutes=interval_minutes)
    start, end = active_hours
    if candidate.hour >= end:
        candidate = (candidate + timedelta(days=1)).replace(hour=start, minute=0, second=0, microsecond=0)
    elif candidate.hour < start:
        candidate = candidate.replace(hour=start, minute=0, second=0, microsecond=0)
    while candidate.weekday() >= 5:
        candidate += timedelta(days=1)
    return candidate

