def truncate_middle(text, limit):
    if limit < 5:
        raise ValueError("limit too small")
    if len(text) <= limit:
        return text
    keep = limit - 3
    head = keep - keep // 2
    return text[:head] + "..." + text[len(text) - keep // 2:]

