def column_stats(engine, table_name, column_name, buckets=10):
    inspector = inspect(engine)
    if table_name not in inspector.get_table_names():
        raise ValueError("unknown table")
    known = {col["name"] for col in inspector.get_columns(table_name)}
    if column_name not in known:
        raise ValueError("unknown column")
    preparer = engine.dialect.identifier_preparer
    table = preparer.quote(table_name)
    column = preparer.quote(column_name)
    with engine.connect() as conn:
        low, high, count = conn.execute(text(f"SELECT MIN({column}), MAX({column}), COUNT({column}) FROM {table}")).one()
        if count == 0 or low == high:
            return {"count": count, "min": low, "max": high, "buckets": []}
        width = (high - low) / buckets
        result = []
        for index in range(buckets):
            start = low + index * width
            end = start + width
            hits = conn.execute(
                text(f"SELECT COUNT(*) FROM {table} WHERE {column} >= :start AND {column} < :end"),
                {"start": start, "end": end},
            ).scalar()
            result.append({"start": start, "end": end, "count": hits})
    return {"count": count, "min": low, "max": high, "buckets": result}

def tally_by(conn, table, group_column, since, top=10):
    allowed = {
        "orders": ("status", "region", "channel"),
        "visits": ("page", "country", "device"),
    }
    if table not in allowed or group_column not in allowed[table]:
        raise ValueError("cannot group that table by that column")
    query = sql.SQL(
        "SELECT {col}, COUNT(*) AS n FROM {tbl} WHERE created_at >= %s GROUP BY {col} ORDER BY n DESC LIMIT %s"
    ).format(col=sql.Identifier(group_column), tbl=sql.Identifier(table))
    with conn.cursor() as cur:
        cur.execute(query, (since, int(top)))
        rows = cur.fetchall()
    total = sum(count for _, count in rows)
    result = []
    for label, count in rows:
        share = round(100.0 * count / total, 1) if total else 0.0
        result.append({"label": label, "count": count, "share": share})
    log.info("tally of %s by %s: %s groups", table, group_column, len(result))
    return result

